import 'package:flutter/foundation.dart';
import 'deployment_config.dart';
import 'package:shared_preferences/shared_preferences.dart';
class DesktopSettings{DesktopSettings({this.python='python',this.engineDirectory='',this.checkpoint='',this.outputDirectory='',this.darkMode=false,String? apiUrl}):apiUrl=apiUrl??configuredApiUrl();String python,engineDirectory,checkpoint,outputDirectory,apiUrl;bool darkMode;}
class SettingsService{Future<DesktopSettings>load()async{final p=await SharedPreferences.getInstance();return DesktopSettings(python:p.getString('python')??'python',engineDirectory:p.getString('engineDirectory')??'',checkpoint:p.getString('checkpoint')??'',outputDirectory:p.getString('outputDirectory')??'',darkMode:p.getBool('darkMode')??false,apiUrl:kReleaseMode?configuredApiUrl():(p.getString('apiUrl')??configuredApiUrl()));}Future<void>save(DesktopSettings s)async{final p=await SharedPreferences.getInstance();await p.setString('python',s.python);await p.setString('engineDirectory',s.engineDirectory);await p.setString('checkpoint',s.checkpoint);await p.setString('outputDirectory',s.outputDirectory);await p.setBool('darkMode',s.darkMode);await p.setString('apiUrl',s.apiUrl);}}
